mapper.sql:
WHERE nc.deleted = 0

    AND nc.typeString = #{typeString}


    AND nc.visitTime >= #{startTime}


    AND nc.visitTime <= #{endTime}

mapper.select:
SELECT
    ROUND(COALESCE((
        SELECT SUM(nc2.amount) FROM bq_bill_not_charged nc2
        WHERE nc2.deleted = 0

            AND nc2.typeString = #{typeString}


            AND nc2.visitTime >= #{startTime}


            AND nc2.visitTime <= #{endTime}

    ), 0), 2) AS totalAmount,
    0 AS actualAmount,
    ROUND(COALESCE((
        SELECT SUM(r.returnAmount) FROM bq_bill_refund r
        WHERE r.deleted = 0

            AND r.returnTime >= #{startTime}


            AND r.returnTime <= #{endTime}

    ), 0), 2) AS refundAmount
